package com.isc.identityreference.governance;
import com.isc.identityreference.application.*; import com.isc.identityreference.cache.l1.CaffeineL1Cache; import com.isc.identityreference.cache.redis.RedisL2Cache; import com.isc.identityreference.domain.identity.*; import com.isc.identityreference.domain.lifecycle.IdentityLifecycleState; import java.time.Instant; import java.util.UUID;
public final class DataGovernanceService { private final IdentityReferenceStore store; private final CaffeineL1Cache l1; private final RedisL2Cache l2; private final AuditEventStore audit; private final GovernanceProperties p; public DataGovernanceService(IdentityReferenceStore s,CaffeineL1Cache l,RedisL2Cache r,AuditEventStore a,GovernanceProperties p){store=s;l1=l;l2=r;audit=a;this.p=p;}
 public void auditLookup(IdentityLookupKey k,String provider,String outcome,UUID op,Instant now){if(p.isEnabled())audit.append(new AuditEvent(UUID.randomUUID(),LookupKeyFingerprint.of(k),"LOOKUP_"+outcome,"CLIENT",null,provider,store.currentPolicyVersion(k),null,null,op,now));}
 public java.util.Optional<IdentityReference> retire(IdentityLookupKey k,String actor,String reason,UUID op,Instant now){var cur=store.find(k);if(!p.isEnabled()||cur.isEmpty())return cur;var r=cur.get();if(r.lifecycleState()==IdentityLifecycleState.RETIRED)return cur;var x=r.transitionTo(IdentityLifecycleState.RETIRED,now);store.save(x);evict(k);audit.append(new AuditEvent(UUID.randomUUID(),LookupKeyFingerprint.of(k),"IDENTITY_RETIRED",safe(actor,"ADMIN"),safe(reason,null),provider(r),null,r.lifecycleState().name(),x.lifecycleState().name(),op,now));return java.util.Optional.of(x);}
 public int purgeRetired(Instant now,int limit){if(!p.isEnabled())return 0;int n=0;for(var r:store.findRetiredBefore(now.minus(p.getRetiredRetention()),limit)){if(store.delete(r.lookupKey())){evict(r.lookupKey());audit.append(new AuditEvent(UUID.randomUUID(),LookupKeyFingerprint.of(r.lookupKey()),"IDENTITY_PURGED","SYSTEM","RETENTION",provider(r),null,"RETIRED",null,null,now));n++;}}return n;}
 public int purgeAudit(Instant now,int limit){return p.isEnabled()?audit.purgeBefore(now.minus(p.getAuditRetention()),limit):0;} private void evict(IdentityLookupKey k){String h=LookupKeyFingerprint.of(k);l1.evict(h);if(l2!=null)l2.evict(h);} private static String provider(IdentityReference r){return r.providerRecords().isEmpty()?null:r.providerRecords().getFirst().providerId();} private static String safe(String v,String d){if(v==null||v.isBlank())return d;return v.length()>64?v.substring(0,64):v;}
}
